        while ((1 << log) <= n) log++;

        int[][] up = new int[log][n + 1];
        int[][] minEdge = new int[log][n + 1];
        int[] depth = new int[n + 1];
        int[] stack = new int[n];
        int top = 0;

        stack[top++] = 1;
        up[0][1] = 1;
        minEdge[0][1] = Integer.MAX_VALUE;

        while (top > 0) {
            int v = stack[--top];
            for (int e = head[v]; e != -1; e = next[e]) {
                int u = to[e];
                if (u == up[0][v]) continue;
                up[0][u] = v;
                minEdge[0][u] = weight[e];
                depth[u] = depth[v] + 1;
                stack[top++] = u;
            }
        }

        for (int k = 1; k < log; k++) {
            for (int v = 1; v <= n; v++) {
                int mid = up[k - 1][v];
                up[k][v] = up[k - 1][mid];
                minEdge[k][v] = Math.min(minEdge[k - 1][v], minEdge[k - 1][mid]);
            }
        }

        int c = fs.nextInt();
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < c; i++) {
            int x = fs.nextInt();
            int y = fs.nextInt();
            int answer = Integer.MAX_VALUE;

            if (depth[x] < depth[y]) {
                int temp = x;
                x = y;
                y = temp;
            }

            int diff = depth[x] - depth[y];
            for (int k = 0; k < log; k++) {
                if (((diff >> k) & 1) != 0) {
                    answer = Math.min(answer, minEdge[k][x]);
                    x = up[k][x];
                }
            }

            if (x != y) {
                for (int k = log - 1; k >= 0; k--) {
                    if (up[k][x] != up[k][y]) {
                        answer = Math.min(answer, minEdge[k][x]);
                        answer = Math.min(answer, minEdge[k][y]);
                        x = up[k][x];
                        y = up[k][y];
                    }
                }
                answer = Math.min(answer, minEdge[0][x]);
                answer = Math.min(answer, minEdge[0][y]);
            }

            out.append(answer).append('\n');
        }

        System.out.print(out);
    }
}
